	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void aLogDroppedDuringAHardInvalidationDoesNotKeepTheVersionValid(boolean validation) {
		System.setProperty(LmdbPlanCacheRevalidation.VALIDATION_PROPERTY, Boolean.toString(validation));
		LmdbPlanCacheRevalidationTest outer = new LmdbPlanCacheRevalidationTest();
		try (LmdbPlanCacheRevalidationTest.Harness harness = outer.new Harness()) {
			harness.publish(LmdbPlanCacheRevalidationTest.learned(17L, 3L), true);
			LmdbPlanDecisionCache decisions = harness.decisions();
			Map.Entry<LmdbPlanDecisionCache.PlanFamilyKey, LmdbPlanDecisionCache.FamilyVersion> family = decisions
					.residentFamiliesForTest()
					.entrySet()
					.iterator()
					.next();
			LmdbPlanDecisionCache.PlanVariant champion = family.getValue().dispatcher().variants().get(0);
			assertEquals(validation, champion.keepsReadLog(), "COVERAGE_PREREQUISITE: the build kept its log");
			LmdbPlanDecisionCache.SemanticDependencies stored = family.getValue().semanticDependencies();
			// A hard dependency no longer holds: a newer physical capability generation.
			LmdbPlanDecisionCache.SemanticDependencies current = new LmdbPlanDecisionCache.SemanticDependencies(
					stored.datasetIdentity(), stored.initialBindingSchema(), stored.requiredResultProperties(),
					stored.evaluationProperties(), stored.indexGeneration(), stored.indexIdentity(),
					stored.indexGenerationDependent(), stored.physicalCapabilityGeneration() + 1L,
					stored.optimizerRuleGeneration(), stored.packedRecipeGeneration(),
					stored.evaluationStrategyGeneration(), stored.optimizerConfiguration(),
					stored.physicalProviderIdentity(), stored.dataRevision(), stored.dataRevisionDependent(),
					stored.providerCacheIdentity());
			decisions.setBeforeHardInvalidationForTest(decisions::dropReadLogsForTest);

			LmdbPlanDecisionCache.LookupDecision decision = decisions.lookupExact(
					family.getValue().exactAliases().keySet().iterator().next(),
					new LmdbPlanDecisionCache.LookupRequest(current, champion.evidenceSnapshot(),
							LmdbPlanDecisionCache.InvocationFeatures.empty(), 0.01d, true, false, false));

			LmdbPlanDecisionCache.FamilyVersion after = decisions.residentFamiliesForTest().get(family.getKey());
			assertAll(
					() -> assertEquals("semantic-dependency-mismatch",
							assertInstanceOf(LmdbPlanDecisionCache.ReplanBeforeUse.class, decision).reason()),
					() -> assertEquals(LmdbPlanDecisionCache.SemanticValidity.HARD_INVALID,
							after.semanticValidity(), "a log drop never keeps a version valid"),
					() -> assertFalse(after.dispatcher().variants().get(0).keepsReadLog(),
							"the dropped log stays dropped"),
					() -> assertEquals(LmdbPlanCacheRevalidationTest.recomputedCharges(decisions),
							harness.cache.retainedBytes(), "charged bytes equal a recomputation"));
		}
	}

	/** A request of another key whose planning runs {@code during} and whose plan is never retainable. */
	private void unretainableRequest(LmdbPipelinePlanCache cache, Runnable during) {
		QueryRoot source = LmdbPlanCacheRevalidationTest.query("_anon_o" + sources.incrementAndGet(),
				"urn:refresh:" + OTHER);
		LmdbPipelinePlanCache.Context context = LmdbPlanCacheRevalidationTest.learned(17L, 3L);
		cache.getOrComputePlan(source, context, context::revision, () -> {
			during.run();
			return new LmdbPipelinePlanCache.PlanComputation(source,
					LmdbPlanCacheRevalidationTest.replayOnlySummary(), null);
		}, () -> Long.MIN_VALUE, null);
	}

	private static LmdbPlanDecisionCache.FamilyVersion family(LmdbPipelinePlanCache cache, int key) {
		LmdbPlanDecisionCache.PlanVariant variant = variant(cache, key);
		for (LmdbPlanDecisionCache.FamilyVersion family : cache.decisionCacheForTest()
				.residentFamiliesForTest()
				.values()) {
			if (family.dispatcher().variants().stream().anyMatch(candidate -> candidate == variant)) {
				return family;
			}
		}
		throw new AssertionError("no resident family of key " + key);
	}

	/** A ranked request of key {@code key} whose planning reads {@code reads} learned keys; returns whether it hit. */
	private boolean request(LmdbPipelinePlanCache cache, int key, int reads, LmdbPipelinePlanCache.Context context) {
		// A log whose size the test sets: keys with exact evidence keep their objects in both encodings (a compact log
		// keeps only a digest for a read that found nothing).
		for (int read = 0; read < reads; read++) {
			if (taught.add("refresh-" + key + "-" + read)) {
				LmdbPlanCacheRevalidationTest.teach(stats,
						LmdbPlanCacheRevalidationTest.logical("refresh-" + key + "-" + read), 40, 7L);
			}
		}
		QueryRoot source = LmdbPlanCacheRevalidationTest.query("_anon_f" + sources.incrementAndGet(),
				"urn:refresh:" + key);
		return cache.getOrComputePlan(source, context, context::revision, () -> {
			for (int read = 0; read < reads; read++) {
				LmdbPlanCacheRevalidationTest.logicalRead(stats,
						LmdbPlanCacheRevalidationTest.logical("refresh-" + key + "-" + read));
			}
			source.setStringMetricPlanned(LmdbCascadesOptimizer.APPLIED_METRIC, "true");
			return new LmdbPipelinePlanCache.PlanComputation(source, LmdbPlanCacheRevalidationTest.rankedSummary(),
					refreshWork(key));
		}, () -> Long.MIN_VALUE,
				new LmdbPlanCacheRevalidationTest.StubValidator(LmdbPlanningReadLog.Verdict.IDENTICAL)).cacheHit();
	}

	static LmdbPlanDecisionCache.DetachedRefreshWork refreshWork(int key) {
		TupleExpr detached = LmdbPlanCacheRevalidationTest.query("_anon_r" + key, "urn:refresh:" + key);
		return new LmdbPlanDecisionCache.DetachedRefreshWork() {
			@Override
			public LmdbPlanDecisionCache.RefreshComputation execute() {
				TupleExpr refreshed = detached.clone();
				refreshed.setStringMetricPlanned(LmdbCascadesOptimizer.APPLIED_METRIC, "true");
				LmdbPlanDecisionCache.EvidenceSnapshot evidence = LmdbPipelinePlanCache
						.evidence(LmdbPlanCacheRevalidationTest.learned(17L, 3L).revision().planningRevisions());
				return new LmdbPlanDecisionCache.RefreshComputation(evidence, evidence, refreshed,
						"refreshed-physical", new LmdbPlanDecisionCache.EstimatedCostInterval(0.5d, 0.5d),
						new LmdbPlanDecisionCache.EstimatedCostInterval(1.0d, 1.0d),
						LmdbPipelinePlanCache.certificate(LmdbPlanCacheRevalidationTest.rankedSummary(),
								evidence.globalEpoch()),
						LmdbPlanDecisionCache.PlanStabilityEnvelope.exact(evidence), 1024L, 1L, true, this);
			}

			@Override
			public long retainedBytes() {
				return 0L;
			}
		};
	}

	/** Waits, without sleeping, until every submitted refresh task has finished (an exact count). */
	static void awaitRefreshesIdle(LmdbPipelinePlanCache cache) {
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(60);
		while (!cache.decisionCacheForTest().refreshTasksIdleForTest()) {
			assertTrue(System.nanoTime() < deadline, "refresh tasks did not finish");
			Thread.onSpinWait();
		}
	}

	private static LmdbPlanDecisionCache.PlanVariant variant(LmdbPipelinePlanCache cache, int key) {
		for (LmdbPlanDecisionCache.FamilyVersion family : cache.decisionCacheForTest()
				.residentFamiliesForTest()
				.values()) {
			for (LmdbPlanDecisionCache.PlanVariant variant : family.dispatcher().variants()) {
				TupleExpr plan = variant.champion().materialize();
				TupleExpr arg = plan instanceof QueryRoot root ? root.getArg() : plan;
				if (arg instanceof Projection projection && projection.getArg() instanceof StatementPattern pattern
						&& ("urn:refresh:" + key).equals(pattern.getPredicateVar().getValue().stringValue())) {
					return variant;
				}
			}
		}
		throw new AssertionError("no resident variant of key " + key);
	}
